const MODE = 'all'; // dryrun | all
const b = $input.first().json; if (!Array.isArray(b.keys)) throw new Error('fetch failed');
const LING = new Set(['daniel@dgmultilingualservices.com','qrcodelocalization@gmail.com','therese.svardsten@gmail.com','vidiasc@gmail.com','michal.tosza@translators.org.pl','47natcha@gmail.com','dmluciahorea@gmail.com','roxanamoldovan25@gmail.com','kenneth@phraseit.dk','ilaria.roncaglia@gmail.com','farahputri@gmail.com','mjlocalize@gmail.com','sara.guinot.trad@gmail.com','mteres@terestraducciones.com','arandatrad@gmail.com']);
const rep = (t, pairs) => { for (const [a, c] of pairs) t = t.split(a).join(c); return t; };
const out = []; const skipped = [];
for (const k of b.keys) {
  const name = k.key_name.web || k.key_name.other;
  const T = {}; for (const tr of k.translations) T[tr.language_iso] = tr;
  if (!(T.en && T.en.translation.includes('Terms of Use'))) continue;
  const trs = [];
  for (const iso of Object.keys(T)) {
    if (iso === 'en') continue; const t = T[iso].translation; if (!t) continue; let n = t;
    if (iso === 'es') {
      if (name.endsWith('agree_description_no_trial')) n = rep(n, [['acepta que se le cobren','aceptas que se te cobren'],['Puede cancelar','Puedes cancelar'],['también acepta nuestros','también aceptas nuestras'],['y reconoce nuestra','y reconoces nuestra']]);
      n = rep(n, [['nuestros <terms>Términos de uso','nuestras <terms>Condiciones de uso'],['<terms>Condiciones del servicio','<terms>Condiciones de uso']]);
      if (n.trim() === 'Términos de uso') n = 'Condiciones de uso';
    }
    if (iso === 'id') n = rep(n, [['Ketentuan Penggunaan','Syarat Penggunaan']]);
    if (iso === 'th') n = rep(n, [['ข้อกำหนดการใช้งาน','เงื่อนไขการใช้บริการ']]);
    if (iso === 'ms') n = rep(n, [['Syarat Penggunaan','Terma Penggunaan']]);
    if (iso === 'it') n = rep(n, [['Termini di utilizzo',"Termini d'utilizzo"]]);
    if (iso === 'da') n = rep(n, [['Brugsvilkår','Vilkår for brug']]);
    if (iso === 'ro') n = rep(n, [['Termenii și condițiile noastre de utilizare','Termenii de utilizare'],['Termenii și condițiile de utilizare','Termenii de utilizare']]);
    if (iso === 'pl') n = rep(n, [['<terms>Warunki użytkowania</terms>','<terms>Warunki korzystania z usług</terms>'],['<terms>Warunki korzystania</terms>','<terms>Warunki korzystania z usług</terms>'],['<terms>Zasad świadczenia usług</terms>','<terms>Warunków korzystania z usług</terms>']]);
    if (iso === 'ko') n = rep(n, [['이용 약관','이용약관'],['<terms>이용약관(</terms> ) 및 <privacy>개인정보 처리방침(</privacy>)에','<terms>이용약관</terms> 및 <privacy>개인정보 처리방침</privacy>에']]);
    if (iso === 'sv' && t.trim() !== 'Användarvillkor') n = rep(n, [['<terms>Användarvillkor</terms>','<terms>användarvillkor</terms>'],['<privacy>Integritetspolicy</privacy>','<privacy>integritetspolicy</privacy>']]);
    if (n !== t) { if (LING.has(T[iso].modified_by_email)) { skipped.push(iso + ' ' + name); continue; } trs.push({ language_iso: iso, translation: n }); }
  }
  if (trs.length) out.push({ key_id: k.key_id, translations: trs });
}
return [{ json: { mode: MODE, n: out.reduce((a, e) => a + e.translations.length, 0), skipped, body: { keys: MODE === 'all' ? out : [] }, expected: out } }];

const c = $('Build').first().json; const rb = $input.first().json;
if (!Array.isArray(rb.keys)) throw new Error('readback failed');
const M = {}; for (const k of rb.keys) for (const t of (k.translations||[])) M[k.key_id + '|' + t.language_iso] = t.translation;
let ok = 0; const bad = [];
for (const e of c.expected) for (const t of e.translations) { const got = M[e.key_id + '|' + t.language_iso]; if (got === t.translation) ok++; else bad.push({ key_id: e.key_id, iso: t.language_iso }); }
let wr; try { wr = JSON.stringify($('WRITE keys').first().json).slice(0,300); } catch (e) { wr = 'not run'; }
return [{ json: { mode: c.mode, planned: c.n, skipped: c.skipped, ok, mismatched: bad.length, bad: bad.slice(0,50), expected: c.expected, write_raw: wr } }];
